            <!-- v1.25.1: \u0641\u0631\u0635\u062A\u200C\u0647\u0627\u06CC \u062C\u0627\u0645\u067E \u0641\u06CC\u0644\u062F \u06A9\u0627\u0631\u0645\u0632\u062F \u0646\u062F\u0627\u0631\u062F \u2014 \u062F\u0631 \u0647\u0631 \u0686\u0647\u0627\u0631 \u0632\u06CC\u0631\u062D\u0627\u0644\u062A \u0633\u0647\u0645\u06CC \u062E\u0631\u06CC\u062F\u0647/\u0641\u0631\u0648\u062E\u062A\u0647 \u0646\u0645\u06CC\u200C\u0634\u0648\u062F \u0648 \u0647\u0645\u0647\u0654 \u0645\u062D\u0627\u0633\u0628\u0627\u062A \u0628\u0627 \u06A9\u0627\u0631\u0645\u0632\u062F \u0635\u0641\u0631 \u0627\u0633\u062A -->
            <div class="tsext-jamp-sub active" id="tsext-jamp-sub-yield" data-jampsub="yield">
              <div class="tsext-row">
                <select id="tsext-jamp-old-yield" class="tsext-input tsext-select" style="flex:1;" title="\u0642\u0631\u0627\u0631\u062F\u0627\u062F \u0641\u0639\u0644\u06CC\u200C\u062A\u0627\u0646 \u0631\u0627 \u0627\u0632 \u0632\u0646\u062C\u06CC\u0631\u0647 \u0627\u0646\u062A\u062E\u0627\u0628 \u06A9\u0646\u06CC\u062F \u2014 \u0641\u0642\u0637 \u0642\u0631\u0627\u0631\u062F\u0627\u062F\u0647\u0627\u06CC \u0628\u0627 \u0633\u0631\u0631\u0633\u06CC\u062F \u062F\u0648\u0631\u062A\u0631 \u0628\u0631\u0631\u0633\u06CC \u0645\u06CC\u200C\u0634\u0648\u0646\u062F">
                  <option value="">\u0642\u0631\u0627\u0631\u062F\u0627\u062F \u0641\u0639\u0644\u06CC (\u0632\u0646\u062F\u0647)</option>
                </select>
              </div>
              <div class="tsext-tickmode-note" title="\u0628\u0627\u0632\u062F\u0647\u06CC (\u0628\u062F\u0648\u0646 \u0641\u06CC\u0644\u062F \u062F\u0633\u062A\u06CC): \u0642\u0631\u0627\u0631\u062F\u0627\u062F \u062C\u0627\u0631\u06CC \u0631\u0627 \u0627\u0632 \u0641\u0647\u0631\u0633\u062A \u0627\u0646\u062A\u062E\u0627\u0628 \u06A9\u0646\u06CC\u062F \u2014 \u0627\u0639\u0645\u0627\u0644\u060C \u067E\u0631\u0645\u06CC\u0648\u0645 \u0622\u0641\u0633\u062A \u0648 \u0631\u0648\u0632\u0645\u0627\u0646\u062F\u0647 \u0647\u0645\u0647 \u0627\u0632 \u0642\u06CC\u0645\u062A \u0632\u0646\u062F\u0647\u0654 \u0647\u0645\u0627\u0646 \u0642\u0631\u0627\u0631\u062F\u0627\u062F \u0645\u06CC\u200C\u0622\u06CC\u062F. \u0641\u0642\u0637 \u0642\u0631\u0627\u0631\u062F\u0627\u062F\u0647\u0627\u06CC \u0628\u0627 \u0631\u0648\u0632 \u0645\u0627\u0646\u062F\u0647 \u0628\u06CC\u0634\u062A\u0631 \u0627\u0632 \u062C\u0627\u0631\u06CC \u0628\u0631\u0631\u0633\u06CC \u0645\u06CC\u200C\u0634\u0648\u0646\u062F. \u0641\u0631\u0645\u0648\u0644: \u0633\u0647\u0645 \u067E\u0627\u06CC\u0647 \u062C\u062F\u06CC\u062F = \u0627\u0639\u0645\u0627\u0644 \u062C\u0627\u0631\u06CC + \u067E\u0631\u0645\u06CC\u0648\u0645 \u0622\u0641\u0633\u062A \u0632\u0646\u062F\u0647 \xB7 \u0633\u067E\u0633 \u0645\u062B\u0644 \u0645\u062B\u0628\u062A\u200C\u067E\u0646\u062C \u0628\u0627 \u06A9\u0627\u0631\u0645\u0632\u062F \u0635\u0641\u0631 \u0645\u062D\u0627\u0633\u0628\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F (\u0633\u0648\u062F \u0645\u0627\u0647\u0627\u0646\u0647). \u0647\u06CC\u0686 \u0641\u06CC\u0644\u062F \u062F\u0633\u062A\u06CC \u0627\u0636\u0627\u0641\u06CC \u0646\u062F\u0627\u0631\u062F \u2014 \u0645\u062D\u0627\u0633\u0628\u0627\u062A \u062F\u0642\u06CC\u0642\u0627\u064B \u0645\u062B\u0644 \u0642\u0628\u0644 \u0627\u0633\u062A."><span>\u25C8</span><span><b>\u0628\u0627\u0632\u062F\u0647\u06CC (\u0628\u062F\u0648\u0646 \u0641\u06CC\u0644\u062F \u062F\u0633\u062A\u06CC):</b> \u0642\u0631\u0627\u0631\u062F\u0627\u062F \u062C\u0627\u0631\u06CC \u0631\u0627 \u0627\u0646\u062A\u062E\u0627\u0628 \u06A9\u0646\u06CC\u062F\u061B \u0633\u0647\u0645 \u067E\u0627\u06CC\u0647 \u062C\u062F\u06CC\u062F = \u0627\u0639\u0645\u0627\u0644 \u062C\u0627\u0631\u06CC + \u067E\u0631\u0645\u06CC\u0648\u0645 \u0622\u0641\u0633\u062A \u0632\u0646\u062F\u0647. \u0641\u0642\u0637 \u0633\u0631\u0631\u0633\u06CC\u062F\u0647\u0627\u06CC \u062F\u0648\u0631\u062A\u0631\u060C \u0628\u062F\u0648\u0646 \u06A9\u0627\u0631\u0645\u0632\u062F.</span></div>
            </div>

